package com.healthcare.service;
import com.healthcare.entity.*;import com.healthcare.exception.ApiException;import com.healthcare.repository.*;import java.time.Instant;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ClinicalService {
 private final UserRepository users;private final PatientRepository patients;private final DoctorRepository doctors;private final AppointmentRepository appointments;private final MedicalRecordRepository records;private final PrescriptionRepository prescriptions;
 public ClinicalService(UserRepository u,PatientRepository p,DoctorRepository d,AppointmentRepository a,MedicalRecordRepository r,PrescriptionRepository pr){users=u;patients=p;doctors=d;appointments=a;records=r;prescriptions=pr;}
 public record ClinicalInput(Long patientId,Long appointmentId,String diagnosis,String allergies,String notes,String medicines){}
 public record RecordView(Long id,Long patientId,Long doctorId,String diagnosis,String allergies,String notes,Instant createdAt){}
 public record PrescriptionView(Long id,Long patientId,Long doctorId,Long appointmentId,String diagnosis,String notes,String medicines,Instant createdAt){}
 public List<RecordView> records(String email,Long patientId){AppUser u=user(email);Patient p=patient(patientId);if(u.getRole()==Role.PATIENT&&!p.getUser().getId().equals(u.getId()))throw ApiException.forbidden();if(u.getRole()==Role.DOCTOR&&!related(doctors.findByUserId(u.getId()).orElseThrow(ApiException::forbidden),p))throw ApiException.forbidden();if(u.getRole()==Role.ADMIN){}return records.findByPatientIdOrderByCreatedAtDesc(patientId).stream().map(r->new RecordView(r.getId(),patientId,r.getDoctor().getId(),r.getDiagnosis(),r.getAllergies(),r.getNotes(),r.getCreatedAt())).toList();}
 @Transactional public RecordView addRecord(String email,ClinicalInput i){Doctor d=doctor(email);Patient p=patient(i.patientId());checkRelated(d,p);MedicalRecord r=records.save(new MedicalRecord(p,d,required(i.diagnosis()),i.allergies(),i.notes()));return new RecordView(r.getId(),p.getId(),d.getId(),r.getDiagnosis(),r.getAllergies(),r.getNotes(),r.getCreatedAt());}
 public List<PrescriptionView> prescriptions(String email,Long patientId){AppUser u=user(email);List<Prescription> found;if(u.getRole()==Role.PATIENT){Patient p=patients.findByUserId(u.getId()).orElseThrow(ApiException::forbidden);if(patientId!=null&&!patientId.equals(p.getId()))throw ApiException.forbidden();found=prescriptions.findByPatientIdOrderByCreatedAtDesc(p.getId());}else if(u.getRole()==Role.DOCTOR){Doctor d=doctors.findByUserId(u.getId()).orElseThrow(ApiException::forbidden);found=prescriptions.findByDoctorIdOrderByCreatedAtDesc(d.getId());if(patientId!=null)found=found.stream().filter(x->x.getPatient().getId().equals(patientId)).toList();}else found=patientId==null?prescriptions.findAll():prescriptions.findByPatientIdOrderByCreatedAtDesc(patientId);return found.stream().map(this::view).toList();}
 @Transactional public PrescriptionView addPrescription(String email,ClinicalInput i){Doctor d=doctor(email);Patient p=patient(i.patientId());checkRelated(d,p);Appointment a=null;if(i.appointmentId()!=null){a=appointments.findById(i.appointmentId()).orElseThrow(()->ApiException.notFound("Appointment not found"));if(!a.getDoctor().getId().equals(d.getId())||!a.getPatient().getId().equals(p.getId()))throw ApiException.forbidden();}Prescription r=prescriptions.save(new Prescription(p,d,a,required(i.diagnosis()),i.notes(),required(i.medicines())));return view(r);}
 private PrescriptionView view(Prescription r){return new PrescriptionView(r.getId(),r.getPatient().getId(),r.getDoctor().getId(),r.getAppointment()==null?null:r.getAppointment().getId(),r.getDiagnosis(),r.getNotes(),r.getMedicines(),r.getCreatedAt());}
 private void checkRelated(Doctor d,Patient p){if(!appointments.existsByDoctorIdAndPatientId(d.getId(),p.getId()))throw new ApiException(HttpStatus.FORBIDDEN,"Doctor has no appointment relationship with this patient");}
 private String required(String x){if(x==null||x.isBlank())throw new ApiException(HttpStatus.BAD_REQUEST,"Diagnosis and medicines are required");return x.trim();} private AppUser user(String e){return users.findByEmailIgnoreCase(e).orElseThrow(ApiException::forbidden);} private Doctor doctor(String e){AppUser u=user(e);if(u.getRole()!=Role.DOCTOR)throw ApiException.forbidden();return doctors.findByUserId(u.getId()).orElseThrow(ApiException::forbidden);} private Patient patient(Long id){return patients.findById(id).orElseThrow(()->ApiException.notFound("Patient not found"));} private boolean related(Doctor d,Patient p){return appointments.existsByDoctorIdAndPatientId(d.getId(),p.getId());}
}
